    assign term_partial_b[26][0] = term_q[26][11] ^ c251 ^ c2381 ^ c4051;
    assign term_partial_b[26][1] = c7741 ^ c8875;
    assign term_partial_b[26][2] = c251 ^ c759 ^ c7751;
    assign term_partial_b[26][3] = term_q[26][0] ^ c10382;
    assign term_partial_b[26][4] = c937 ^ c8470;
    assign term_partial_b[26][5] = c4040 ^ c8470;
    assign term_partial_b[26][6] = c4040 ^ c8467;
    assign term_partial_b[26][7] = c4040 ^ c8877;
