    assign term_partial_b[27][0] = term_q[27][4] ^ c334 ^ c1014 ^ c2782;
    assign term_partial_b[27][1] = term_q[27][10] ^ c1572 ^ c7811;
    assign term_partial_b[27][2] = c4072 ^ c7813;
    assign term_partial_b[27][3] = c4068 ^ c5909;
    assign term_partial_b[27][4] = c3287 ^ c4068 ^ c7797;
    assign term_partial_b[27][5] = term_q[27][5] ^ c414 ^ c2784 ^ c4072;
    assign term_partial_b[27][6] = term_q[27][6] ^ c3285 ^ c10199;
    assign term_partial_b[27][7] = term_q[27][7] ^ c334 ^ c414 ^ c7783;
    assign term_partial_b[27][8] = c3285 ^ c4068 ^ c7785;
    assign term_partial_b[27][9] = c356 ^ c2782 ^ c4070;
    assign term_partial_b[27][10] = c356 ^ c7787 ^ c10199;
    assign term_partial_b[27][11] = c3287 ^ c4056 ^ c5909;
    assign term_partial_b[27][12] = c27 ^ c414 ^ c2782 ^ c7792;

    always @* begin
        correction_work = '0;
        roots_full = 0;
        roots_partial_a = 0;
        roots_partial_b = 0;
        for (lane = 0; lane < W; lane = lane + 1) begin
            value = eval_matrix[lane*M +: M];
            correction_work[W-1-lane] = (value == 0);
            if (value == 0) begin
                roots_full = roots_full + 1;
                if (lane < PARTIAL_A)
                    roots_partial_a = roots_partial_a + 1;
                if (lane < PARTIAL_B)
                    roots_partial_b = roots_partial_b + 1;
            end
        end

        if (replay_count_i == W)
            roots_this_beat = roots_full;
        else if (replay_count_i == PARTIAL_A)
            roots_this_beat = roots_partial_a;
        else
            roots_this_beat = roots_partial_b;

        info_bits_o = replay_bits_i ^ correction_work;
        valid_info = 0;
        if (seen_q < K)
            valid_info = ((K - seen_q) < replay_count_i) ? (K - seen_q) : replay_count_i;
        info_count_o = valid_info[COUNT_W-1:0];
    end

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            seen_q <= '0;
            roots_q <= '0;
            busy_q <= 1'b0;
            done_o <= 1'b0;
            success_o <= 1'b0;
            error_count_o <= '0;
            for (coefficient = 0; coefficient <= T; coefficient = coefficient + 1)
                term_q[coefficient] <= '0;
        end else begin
            done_o <= 1'b0;
            if (start_i && !busy_q) begin
                seen_q <= '0;
                roots_q <= '0;
                busy_q <= 1'b1;
                success_o <= 1'b0;
                error_count_o <= '0;
                for (coefficient = 0; coefficient <= T; coefficient = coefficient + 1)
                    term_q[coefficient] <= gf_mul(
                        locator_i[coefficient*M +: M],
                        INIT_FACTOR[coefficient*M +: M]);
            end else if (replay_valid_i && replay_ready_o) begin
                for (coefficient = 0; coefficient <= T; coefficient = coefficient + 1) begin
                    if (replay_count_i == W)
                        term_q[coefficient] <= term_full[coefficient];
                    else if (replay_count_i == PARTIAL_A)
                        term_q[coefficient] <= term_partial_a[coefficient];
                    else
                        term_q[coefficient] <= term_partial_b[coefficient];
                end
                roots_q <= roots_q + roots_this_beat;
                seen_q <= seen_q + replay_count_i;
                if (seen_q + replay_count_i == N) begin
                    busy_q <= 1'b0;
                    done_o <= 1'b1;
                    error_count_o <= roots_q + roots_this_beat;
                    success_o <= (roots_q + roots_this_beat) == degree_i;
                end
            end
        end
    end
endmodule

`default_nettype wire
